cat > src/server/services/issue-dependency-service.ts <<'EOF'
/**
 * Issue dependencies ("blocked by" links): the link CRUD, the completion gate
 * `IssueService` consults, and the reaction that tells an assignee their issue
 * was unblocked.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived, isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { issueResource, requireFound } from "./_support";
import { notify } from "./notification-service";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";

export type BlockerInput = {
  orgId: OrgId;
  issueId: IssueId;
  blockerId: IssueId;
};

/** Raised when an issue cannot be completed because blockers are still open. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly blockerIds: readonly IssueId[]) {
    super(`Issue is blocked by ${blockerIds.length} open issue(s)`);
    this.name = "IssueBlockedError";
  }
}

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/** An issue counts as an open blocker while live and not done/canceled. */
function isOpen(issue: Issue): boolean {
  return !isArchived(issue) && !isClosedStatus(issue.status);
}

export async function addBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );

  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  if (input.issueId === input.blockerId) {
    throw new Error("An issue cannot block itself");
  }

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
  if (existing) return existing;

  if (await reaches(input.orgId, input.blockerId, input.issueId)) {
    throw new Error("Blocking link would create a dependency cycle");
  }

  return dependencyRepo.insertDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
    actor.userId,
  );
}

export async function removeBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
}

export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return dependencyRepo.listLiveBlockers(orgId, issueId);
}

/**
 * Completion gate, called by `IssueService` before any move to `done`.
 * Throws `IssueBlockedError` naming exactly the open blockers.
 */
export async function assertNotBlocked(
  orgId: OrgId,
  issueId: IssueId,
): Promise<void> {
  const open = await dependencyRepo.listOpenBlockerIds(orgId, issueId);
  if (open.length > 0) throw new IssueBlockedError(open);
}

/** True when `target` is reachable from `start` following "blocked by" links. */
async function reaches(
  orgId: OrgId,
  start: IssueId,
  target: IssueId,
): Promise<boolean> {
  const links = await dependencyRepo.listDependencies(orgId);
  const next = new Map<IssueId, IssueId[]>();
  for (const link of links) {
    const list = next.get(link.issueId) ?? [];
    list.push(link.blockerId);
    next.set(link.issueId, list);
  }

  const seen = new Set<IssueId>([start]);
  const queue: IssueId[] = [start];
  while (queue.length > 0) {
    const current = queue.pop() as IssueId;
    if (current === target) return true;
    for (const blockerId of next.get(current) ?? []) {
      if (!seen.has(blockerId)) {
        seen.add(blockerId);
        queue.push(blockerId);
      }
    }
  }
  return false;
}

/**
 * Called once a blocker has just gone from open to closed: notifies the
 * assignee of every live, unfinished issue it blocked that now has no open
 * blocker left.
 */
async function notifyUnblocked(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  for (const issueId of await dependencyRepo.listBlockedIssueIds(
    orgId,
    blockerId,
  )) {
    const blocked = await issueRepo.findIssueById(orgId, issueId);
    if (!blocked || !isOpen(blocked) || blocked.assigneeId === null) continue;
    if ((await dependencyRepo.listOpenBlockerIds(orgId, issueId)).length > 0) {
      continue;
    }

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "An issue was unblocked",
      body: `Issue ${blocked.title} has no open blockers left`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}

/** Bus wiring; attached by `registerEventHandlers()` in `event-registry`. */
export function registerDependencyListeners(): Unsubscribe {
