    await dep.addBlocker(a, inp(B, C));
    await expect(dep.addBlocker(a, inp(C, A))).rejects.toThrow();
    await expect(dep.addBlocker(a, inp(A, A))).rejects.toThrow();
    expect((await dep.listBlockers(a, t.org.id, A.id)).map((i) => i.id)).toEqual([B.id]);
