    console.log(JSON.stringify(page.items.map((n: any) => [n.kind, n.href])));
    expect(await dep.removeBlocker(a, inp(A, B))).toBe(true);
    expect(await dep.removeBlocker(a, inp(A, B))).toBe(false);
  });
});
