import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as dep from "@/server/services/issue-dependency-service";
import * as issueService from "@/server/services/issue-service";
import * as notifRepo from "@/server/repositories/notification-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let t: Tenant;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); t = await createTenant("dep"); registerEventHandlers(); });
afterAll(() => cleanup());

describe("deps", () => {
  it("notifies", async () => {
    const a = t.actors.admin;
    const mk = (title: string, extra = {}) => issueService.createIssue(a, issueInput(t.org.id, t.project.id, { title, ...extra }));
    const A = await mk("Issue A", { assigneeId: t.actors.member.userId });
    const B = await mk("Issue B");
    await dep.addBlocker(a, { orgId: t.org.id, issueId: A.id, blockerId: B.id });
    await issueService.changeIssueStatus(a, { orgId: t.org.id, issueId: B.id, status: "done" });
    const page = await notifRepo.listNotifications({ orgId: t.org.id, recipientId: t.actors.member.userId, unreadOnly: false, limit: 50 } as any);
    expect(page.items.map((n: any) => [n.kind, n.href, n.actorId])).toEqual([["issue_unblocked", `/issues/${A.id}`, a.userId]]);
    // reopen + archive
    await issueService.changeIssueStatus(a, { orgId: t.org.id, issueId: B.id, status: "todo" });
    await issueService.archiveIssue(a, t.org.id, B.id);
    const p2 = await notifRepo.listNotifications({ orgId: t.org.id, recipientId: t.actors.member.userId, unreadOnly: false, limit: 50 } as any);
    expect(p2.items.length).toBe(2);
  });
});
EOF
